// GECICI: dairenin dinlenme konumu ikonun merkezine gore dogru mu.
// Daire dalista translateY 0'a iner; o an merkezi IKONUN merkeziyle
// cakismali. Dinlenmede DAIRE_YUKSEK (35) kadar yukarida durur.
import puppeteer from 'puppeteer-core'

const KROM = 'C:/Program Files/Google/Chrome/Application/chrome.exe'
const t = await puppeteer.launch({ executablePath: KROM, headless: 'new' })
const s = await t.newPage()
await s.setViewport({ width: 390, height: 844, deviceScaleFactor: 2 })

await s.goto('http://127.0.0.1:8080/giris', { waitUntil: 'networkidle0', timeout: 60000 })
const a = await s.$$('input')
await a[0].type('test0@slooin.test', { delay: 10 })
await a[1].type('[SIR-GIZLENDI]', { delay: 10 })
await s.evaluate(() => {
  const h = [...document.querySelectorAll('div,span')].find(
    (e) => e.textContent?.trim() === 'Giriş yap' && e.children.length === 0
  )
  h?.closest('[role="button"]')?.click() ?? h?.click()
})
await new Promise((c) => setTimeout(c, 4500))
await s.goto('http://127.0.0.1:8080/', { waitUntil: 'networkidle0', timeout: 60000 })
await new Promise((c) => setTimeout(c, 1800))

const r = await s.evaluate(() => {
  const bul = (tid) =>
    [...document.querySelectorAll('div')].find((e) => e.getAttribute('data-testid') === tid)
  const daireYuva = bul('aktif-sekme-dairesi')
  // Gorunen yuvarlak: yuvanin ilk cocugu
  const daire = daireYuva?.firstElementChild
  // Ana sayfa AKTIF; onun ikonu gizli ama kutusu duruyor.
  const ikon = bul('sekme-ikonu/')
  // Pasif bir ikon da olcelim (gizli olan kayabilir mi diye)
  const ikonPasif = bul('sekme-ikonu/mesajlar')
  const m = (e) => {
    if (!e) return null
    const b = e.getBoundingClientRect()
    return { merkezY: +(b.y + b.height / 2).toFixed(1), merkezX: +(b.x + b.width / 2).toFixed(1) }
  }
  return { daire: m(daire), ikon: m(ikon), ikonPasif: m(ikonPasif) }
})

console.log('daire (dinlenme) :', JSON.stringify(r.daire))
console.log('aktif ikon kutusu:', JSON.stringify(r.ikon))
console.log('pasif ikon kutusu:', JSON.stringify(r.ikonPasif))

const DAIRE_YUKSEK = 35
if (r.daire && r.ikon) {
  const inisMerkezi = r.daire.merkezY + DAIRE_YUKSEK
  const sapma = +(inisMerkezi - r.ikon.merkezY).toFixed(1)
  console.log('')
  console.log('daire dalista inecegi merkez :', inisMerkezi.toFixed(1))
  console.log('ikonun merkezi               :', r.ikon.merkezY)
  console.log('DIKEY SAPMA                  :', sapma, 'px')
  console.log(Math.abs(sapma) <= 1.5 ? '-> GECTI: daire ikona oturuyor' : '-> SAPMA VAR, paddingBottom ayarlanmali')

  const yatay = +(r.daire.merkezX - r.ikon.merkezX).toFixed(1)
  console.log('YATAY SAPMA                  :', yatay, 'px')
  console.log(Math.abs(yatay) <= 1.5 ? '-> GECTI: yatayda hizali' : '-> yatay sapma var')
}

await t.close()

