  const googleIosSemasi = process.env.GOOGLE_IOS_URL_SCHEME

  return {
    ...config,
    plugins: [
      ...(config.plugins ?? []),
      ['react-native-maps', androidAnahtari ? { androidGoogleMapsApiKey: androidAnahtari } : {}],
      ...(googleIosSemasi
        ? [['@react-native-google-signin/google-signin', { iosUrlScheme: googleIosSemasi }]]
        : []),
    ],
  }
}

