// GECICI: canli yayinda harita ignesine basinca hangi adrese
// gidildigini olcer. Beklenen /harita/<id>, /check-in/<id> DEGIL.
import puppeteer from 'puppeteer-core'

const TABAN = process.env.SLOOIN_TABAN_ADRES ?? 'https://slooin.expo.app'
const KROM = 'C:/Program Files/Google/Chrome/Application/chrome.exe'
const t = await puppeteer.launch({ executablePath: KROM, headless: 'new' })
const s = await t.newPage()
await s.setViewport({ width: 390, height: 844, deviceScaleFactor: 2 })
await s.setGeolocation({ latitude: 40.2261, longitude: 28.8656 })
const ctx = t.defaultBrowserContext()
await ctx.overridePermissions(TABAN, ['geolocation'])

await s.goto(TABAN + '/giris', { waitUntil: 'networkidle0', timeout: 60000 })
const a = await s.$$('input')
await a[0].type('test0@slooin.test', { delay: 10 })
await a[1].type('[SIR-GIZLENDI]', { delay: 10 })
await s.evaluate(() => {
  const h = [...document.querySelectorAll('div,span')].find(
    (e) => e.textContent?.trim() === 'Giriş yap' && e.children.length === 0
  )
  h?.closest('[role="button"]')?.click() ?? h?.click()
})
await new Promise((c) => setTimeout(c, 4500))
await s.goto(TABAN + '/mekanlar', { waitUntil: 'networkidle0', timeout: 60000 })
await new Promise((c) => setTimeout(c, 3000))

const oncekiUrl = s.url()
console.log('baslangic adresi:', oncekiUrl)

// Radardaki mekan noktalari: erisilebilirlik etiketi ad + durum tasiyor.
const tiklandi = await s.evaluate(() => {
  const adaylar = [...document.querySelectorAll('[role="button"]')].filter((e) => {
    const l = e.getAttribute('aria-label') || ''
    return /kişi burada|Sakin|Yoğun|Popüler/i.test(l)
  })
  if (!adaylar.length) return null
  const etiket = adaylar[0].getAttribute('aria-label')
  adaylar[0].click()
  return etiket
})

if (!tiklandi) {
  console.log('SONUC: radar uzerinde tiklanabilir mekan bulunamadi - olculemedi')
} else {
  console.log('tiklanan:', tiklandi)
  await new Promise((c) => setTimeout(c, 2000))
  const yeni = s.url()
  console.log('yeni adres:', yeni)
  const haritaMi = /\/harita\//.test(yeni)
  const checkInMi = /\/check-in\//.test(yeni)
  console.log('')
  console.log('/harita/ mi   :', haritaMi)
  console.log('/check-in/ mi :', checkInMi)
  console.log(
    'SONUC:',
    haritaMi && !checkInMi ? 'GECTI - mekan sayfasi aciliyor' : 'BEKLENEN DEGIL'
  )
}

await t.close()

