{yerlesimler.map(({ mekan, x, y }) => {
  const canli = mekan.kisiSayisi > 0
  return (
    <Pressable
      key={mekan.id}
      style={[stiller.igne, { left: x - 16, top: y - 16 }]}
      onPress={() => onMekanSec?.(mekan.id)}
      accessibilityRole="button"
      accessibilityLabel={
        canli ? `${mekan.ad}, ${mekan.kisiSayisi} kişi burada` : mekan.ad
      }
      hitSlop={6}
    >
