// GECICI: canli yayinda harita ignesine basinca hangi adrese
// gidildigini olcer. Beklenen /harita/<id>, /check-in/<id> DEGIL.
//
// Web surumunde harita bir RADAR ciziyor ama ayni `onMekanSec`
// sozlesmesini kullaniyor, yani tiklama hedefi burada olculebilir.
import puppeteer from 'puppeteer-core'

const TABAN = process.env.SLOOIN_TABAN_ADRES ?? 'https://slooin.expo.app'
const KROM = 'C:/Program Files/Google/Chrome/Application/chrome.exe'
const t = await puppeteer.launch({ executablePath: KROM, headless: 'new' })
const s = await t.newPage()
await s.setViewport({ width: 390, height: 844, deviceScaleFactor: 2 })
await s.setGeolocation({ latitude: 40.2261, longitude: 28.8656 })
await t.defaultBrowserContext().overridePermissions(TABAN, ['geolocation'])

await s.goto(TABAN + '/giris', { waitUntil: 'networkidle0', timeout: 60000 })
const a = await s.$$('input')
await a[0].type('test0@slooin.test', { delay: 10 })
await a[1].type('[SIR-GIZLENDI]', { delay: 10 })
await s.evaluate(() => {
  const h = [...document.querySelectorAll('div,span')].find(
    (e) => e.textContent?.trim() === 'Giriş yap' && e.children.length === 0
  )
  h?.closest('[role="button"]')?.click() ?? h?.click()
})
await new Promise((c) => setTimeout(c, 4500))
await s.goto(TABAN + '/mekanlar', { waitUntil: 'networkidle0', timeout: 60000 })
await new Promise((c) => setTimeout(c, 3000))

console.log('baslangic adresi:', s.url())

// Radar noktasi: haritanin GORSEL ALANI icinde kalan, role=button olan
// ve mutlak konumlandirilmis kucuk oge. Liste satirlarindan boyle
// ayriliyor - onlar genis ve akista.
const secim = await s.evaluate(() => {
  const butonlar = [...document.querySelectorAll('[role="button"]')]
  const aday = butonlar.find((e) => {
    const b = e.getBoundingClientRect()
    const st = getComputedStyle(e)
    return (
      st.position === 'absolute' &&
      b.width > 12 && b.width < 60 &&
      b.height > 12 && b.height < 60 &&
      b.top > 100 && b.top < 500 &&
      (e.getAttribute('aria-label') || '').length > 0
    )
  })
  if (!aday) {
    return {
      bulunamadi: true,
      ornekler: butonlar.slice(0, 12).map((e) => {
        const b = e.getBoundingClientRect()
        return {
          etiket: e.getAttribute('aria-label'),
          pos: getComputedStyle(e).position,
          w: Math.round(b.width), h: Math.round(b.height), top: Math.round(b.top),
        }
      }),
    }
  }
  const etiket = aday.getAttribute('aria-label')
  aday.click()
  return { etiket }
})

if (secim.bulunamadi) {
  console.log('radar noktasi bulunamadi. Ornek butonlar:')
  console.log(JSON.stringify(secim.ornekler, null, 1))
} else {
  console.log('tiklanan igne:', secim.etiket)
  await new Promise((c) => setTimeout(c, 2500))
  const yeni = s.url()
  console.log('yeni adres  :', yeni)
  const haritaMi = /\/harita\//.test(yeni)
  const checkInMi = /\/check-in\//.test(yeni)
  console.log('')
  console.log('SONUC:', haritaMi && !checkInMi
    ? 'GECTI - mekan sayfasi acildi, check-in ekrani DEGIL'
    : `BEKLENEN DEGIL (harita=${haritaMi} checkIn=${checkInMi})`)
}

await t.close()

